package hu.bankmonitor.payments.accounts;

import hu.bankmonitor.payments.common.Currency;

/**
 * An Account as this API reports it: what it holds, and how much of that is still
 * spendable.
 *
 * <p>One representation for every endpoint that answers with an Account, rather than a
 * leaner one for the Account just created. The two figures are what an operator reads —
 * the Reserved Amount is their difference and would be a third number saying nothing new
 * — and a create response shaped differently from a list entry would hand the frontend
 * two Account types generated from one document.
 *
 * <p>Amounts are counts of Minor Units, named as such for the reason
 * {@link CreateAccountRequest} gives.
 */
record AccountResponse(

		long id,

		Currency currency,

		long balanceMinorUnits,

		long availableBalanceMinorUnits) {

	static AccountResponse of(Account account) {
		return new AccountResponse(
				account.getId(),
				account.getCurrency(),
				account.getBalance().minorUnits(),
				account.getAvailableBalance().minorUnits());
	}
}

