package hu.bankmonitor.payments.accounts;

import hu.bankmonitor.payments.common.Money;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * What can be done to an Account, and the only way in from outside this package.
 *
 * <p>The class is package-private and the methods are public, which is the shape design
 * decision 30 warns is load-bearing: {@code @Transactional} on a non-public method is
 * silently ignored under proxy-based AOP, so a transaction would quietly stop existing
 * with no error to read.
 */
@Service
class AccountService {

	private final AccountRepository accounts;

	AccountService(AccountRepository accounts) {
		this.accounts = accounts;
	}

	/**
	 * Opens an Account holding the given amount, in the currency that amount is
	 * denominated in, and returns it with the identifier the database gave it.
	 */
	@Transactional
	public Account open(Money openingBalance) {
		return accounts.save(new Account(openingBalance));
	}
}

